diff --git a/share/messages_to_clients.txt b/share/messages_to_clients.txt
index c28ecd368d19..5f42bcbf09b2 100644
--- a/share/messages_to_clients.txt
+++ b/share/messages_to_clients.txt
@@ -6511,7 +6511,7 @@ ER_ACCESS_DENIED_NO_PASSWORD_ERROR 28000
         swe "Användare '%-.48s'@'%-.64s' är ej berättigad att logga in"
         ukr "Доступ заборонено для користувача: '%-.48s'@'%-.64s'"

-ER_SET_PASSWORD_AUTH_PLUGIN
+OBSOLETE_ER_SET_PASSWORD_AUTH_PLUGIN
         eng "SET PASSWORD has no significance for users authenticating via plugins"

 OBSOLETE_ER_GRANT_PLUGIN_USER_EXISTS
@@ -9733,6 +9733,9 @@ ER_IF_NOT_EXISTS_UNSUPPORTED_TRG_EXISTS_ON_DIFFERENT_TABLE
 ER_IF_NOT_EXISTS_UNSUPPORTED_UDF_NATIVE_FCT_NAME_COLLISION
   eng "This function '%-.192s' has the same name as a native function. The 'IF NOT EXISTS' clause is not supported while creating a loadable function with the same name as a native function."

+ER_SET_PASSWORD_AUTH_PLUGIN_ERROR
+  eng "SET PASSWORD has no significance for user '%s'@'%s' as the authentication method used doesn't store authentication data in the MySQL server. Please consider using ALTER USER instead if you want to change authentication parameters."
+
 #
 #  End of 8.0 error messages (server-to-client).
 #  Do NOT add messages intended for the error log above!
diff --git a/sql/auth/sql_user.cc b/sql/auth/sql_user.cc
index 3863ac9c94a5..ef660d7ca486 100644
--- a/sql/auth/sql_user.cc
+++ b/sql/auth/sql_user.cc
@@ -1535,24 +1535,17 @@ bool set_and_validate_user_attributes(
       }
     }

-    if (!(auth->authentication_flags & AUTH_FLAG_USES_INTERNAL_STORAGE)) {
-      if (command == SQLCOM_SET_PASSWORD) {
-        /*
-          A plugin that does not use internal storage and
-          hence does not support SET PASSWORD
-        */
-        char warning_buffer[MYSQL_ERRMSG_SIZE];
-        snprintf(warning_buffer, sizeof(warning_buffer),
-                 "SET PASSWORD has no significance for user '%s'@'%s' as "
-                 "authentication plugin does not support it.",
-                 Str->user.str, Str->host.str);
-        warning_buffer[MYSQL_ERRMSG_SIZE - 1] = '\0';
-        push_warning(thd, Sql_condition::SL_NOTE, ER_SET_PASSWORD_AUTH_PLUGIN,
-                     warning_buffer);
-        plugin_unlock(nullptr, plugin);
-        what_to_set.m_what = NONE_ATTR;
-        return (false);
-      }
+    if (!(auth->authentication_flags & AUTH_FLAG_USES_INTERNAL_STORAGE) &&
+        command == SQLCOM_SET_PASSWORD) {
+      /*
+        A plugin that does not use internal storage and
+        hence does not support SET PASSWORD
+      */
+      my_error(ER_SET_PASSWORD_AUTH_PLUGIN_ERROR, MYF(0), Str->user.str,
+               Str->host.str);
+      plugin_unlock(nullptr, plugin);
+      what_to_set.m_what = NONE_ATTR;
+      return (true);
     }
   }

